<template>
  <div class="role-management">
    <div class="serch">
      <el-button type="primary" size="small" icon="el-icon-plus" @click="showAddDialog">新增角色</el-button>
    </div>
    <div class="table">
      <div class="jia_table">
        <el-table :data="roles" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }" height="95%">
          <el-table-column prop="index" label="序号" width="50" >
            <template slot-scope="scope">
              {{ scope.$index + 1 }}
            </template>
          </el-table-column>
          <el-table-column prop="permission_name" label="角色" ></el-table-column>
          <el-table-column prop="permission_code" label="角色标识" ></el-table-column>
          <el-table-column prop="permission_content" label="描述" ></el-table-column>
          <el-table-column prop="created_at" label="创建时间" >
            <template slot-scope="scope">
              {{ formatDate(scope.row.created_at) }}
            </template>
          </el-table-column>
          <el-table-column prop="permission_status" label="是否启用" >
            <template slot-scope="scope">
              <el-switch v-model="scope.row.permission_status" active-color="#13ce66" inactive-color="#ff4949" active-value="1" inactive-value="2" @change="handleChangeRoleStatus(scope.row)">
              </el-switch>
            </template>
          </el-table-column>
          <el-table-column label="操作" >
            <template slot-scope="scope">
              <el-button size="mini" type="text" icon="el-icon-edit" @click="showEditDialog(scope.row)">编辑</el-button>
              <el-button size="mini" type="text" icon="el-icon-key" @click="handleAddKey(scope.row)">授权</el-button>
              <el-button size="mini" type="text" icon="el-icon-delete" @click="handleDelete(scope.row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
        <!-- 如果没有数据，显示空状态 -->
        <el-empty v-if="roles.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
      </div>
    </div>
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="500px">
      <el-form :model="formData" ref="formData" :rules="rules" label-width="80px" class="roleForm" label-position="top">
        <el-form-item label="角色名称" prop="permission_name">
          <el-input v-model="formData.permission_name" autocomplete="off" placeholder="请输入角色名称"></el-input>
        </el-form-item>
        <el-form-item label="标识" prop="permission_code">
          <el-input v-model="formData.permission_code" autocomplete="off" placeholder="请输入角色标识"></el-input>
        </el-form-item>
        <el-form-item label="描述" prop="permission_content">
          <el-input v-model="formData.permission_content" autocomplete="off" placeholder="请输入角色描述信息"></el-input>
        </el-form-item>
        <el-form-item label="是否启用" prop="permission_status">
          <el-switch v-model="formData.permission_status" active-color="#13ce66" inactive-color="#ff4949" active-value="1" inactive-value="2"></el-switch>
        </el-form-item>
      </el-form>

      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="handleSubmit">确 定</el-button>
      </div>
    </el-dialog>
    <el-dialog :title="treeTitle" :visible.sync="treeOpen" width="500px">
      <el-tree :data="menuList" show-checkbox node-key="menu_id" ref="tree" highlight-current :props="defaultProps">
      </el-tree>
      <div slot="footer" class="dialog-footer">
        <el-button @click="treeOpen = false">取 消</el-button>
        <el-button type="primary" @click="handleSureKeys()">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>
  
  <script>
import { mapGetters } from 'vuex';
import { Message, MessageBox } from 'element-ui';
import { roleApi } from "../../api/system/role";

export default {
  data() {
    return {
      roles: [],
      dialogVisible: false,
      isNew: true,
      formData: {
        id: null,
        permission_code: null,
        permission_content: null,
        permission_name: null,
        permission_status: null
      },
      rules: {
        permission_name: [
          { required: true, message: '请输入角色名称', trigger: 'blur' }
        ],
        permission_code: [
          { required: true, message: '请输入角色标识', trigger: 'blur' }
        ],
      },
      queryParams: {
        pageSize: 15,
        pageNum: 1,
      },
      pagesizes: [15, 35, 50, 100, 150, 200, 300],
      total: 0,
      menuList: [],//全部菜单信息
      treeTitle: '菜单',
      treeOpen: false,
      defaultProps: {
        children: 'children',
        label: 'menu_name'
      },
      keysId: '',//用于记录当前修改菜单权限的id
    };
  },
  computed: {
    ...mapGetters([
      // 如果使用 Vuex，请根据需要添加 getter
    ]),
    dialogTitle() {
      return this.isNew ? '新增角色' : '编辑角色';
    }
  },
  created() {
    this.getRoleData();//获取角色信息列表
    this.getMenuData();//获取菜单信息
  },
  methods: {
    // 处理表格中的注册时间、更新时间
    formatDate(inputTime) {
      // 解析输入的时间字符串
      const date = new Date(inputTime);

      // 获取年月日时分秒
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0'); // 月份从0开始，需要加1，并补零
      const day = String(date.getDate()).padStart(2, '0');
      const hours = String(date.getHours()).padStart(2, '0');
      const minutes = String(date.getMinutes()).padStart(2, '0');
      const seconds = String(date.getSeconds()).padStart(2, '0');

      // 组合格式化的日期时间字符串
      const formattedDate = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

      return formattedDate;
    },
    formatEnabled(row) {
      return row.enabled ? '是' : '否';
    },
    showAddDialog() {
      this.isNew = true;
      this.formData = {
        name: '',
        identifier: '',
        description: '',
        enabled: true
      };
      this.dialogVisible = true;
    },
    // 获取角色信息，打开编辑弹窗
    showEditDialog(row) {
      this.isNew = false;
      this.formData = row;
      this.dialogVisible = true;
    },
    handleSubmit() {
      if (this.$refs.formData.validate()) {
        if (this.isNew) {
          let form = new FormData()
          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.formData).forEach(key => {
            form.append(key, this.formData[key]);
          });
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          };
          // 新增角色逻辑
          this.$http.post(roleApi.addRole, form, config)
            .then(response => {
              if (response.data.code == 200) {
                this.$message({
                  type: 'success',
                  message: response.data.msg
                })
                this.dialogVisible = false;
              } else {
                this.$message({
                  type: 'warning',
                  message: response.data.msg
                })
              }
              this.getRoleData();
            })
            .catch(rek => {
              console.log(rek)
              this.getRoleData();
              this.dialogVisible = false;
            })
        } else {
          let form = new FormData()
          this.formData.permission_id = this.formData.id
          delete this.formData.id
          delete this.formData.created_at
          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.formData).forEach(key => {
            form.append(key, this.formData[key]);
          });
          let config = {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          };
          // 编辑角色逻辑
          this.$http.post(roleApi.undataRoleMsg, form, config)
            .then(response => {
              if (response.data.code == 200) {
                this.$message({
                  type: 'success',
                  message: response.data.msg
                })
              } else {
                this.$message({
                  type: 'warning',
                  message: response.data.msg
                })
              }
              this.getRoleData();
              this.dialogVisible = false;
            })
            .catch(rek => {
              console.log(rek)
              this.getRoleData();
              this.dialogVisible = false;
            })
        }
      }
    },
    handleDelete(row) {
      MessageBox.confirm('确定删除该角色吗？', '提示', {
        type: 'warning'
      }).then(() => {
        // Message.success('删除成功');
        let formData = {
          permission_id: row.id
        }
        let form = new FormData()
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(formData).forEach(key => {
          form.append(key, formData[key]);
        });
        let config = {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        };
        this.$http.post(roleApi.deleteRole, form, config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: 'success',
                message: response.data.message
              })
            } else {
              this.$message({
                type: 'warning',
                message: response.data.message
              })
            }
            this.getRoleData();
          })
          .catch(rek => {
            console.log(rek)
          })
      }).catch(() => {
        Message.info('已取消删除');
      });
    },
    // 获取角色列表
    getRoleData() {
      this.$http.get(roleApi.getRoleList, {
        params: {
          page: this.queryParams.pageNum,
          per_page: this.queryParams.pageSize
        }
      }).then(response => {
        if (response.data.code == 200) {
          this.roles = response.data.data.data
          this.total = response.data.data.total_items
        }
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 表格中修改角色状态按钮
    handleChangeRoleStatus(row) {
      let data = {
        permission_id: row.id,
        permission_status: row.permission_status
      }
      let form = new FormData()
      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(data).forEach(key => {
        form.append(key, data[key]);
      });
      let config = {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      };
      this.$http.post(roleApi.updataRole, form, config)
        .then(response => {
          if (response.data.code == 200) {
            this.$message({
              type: 'success',
              message: response.data.message
            })
          } else {
            this.$message({
              type: 'warning',
              message: response.data.message
            })
          }
        })
        .catch(rek => {
          console.log(rek)
        })
    },
    // 获取全部菜单信息
    getMenuData() {
      this.$http.get(roleApi.getMenuList)
        .then(response => {
          this.menuList = this.transformMenuData(response.data.data.menu_list)
        })
    },
    // 表格授权按钮
    handleAddKey(row) {
      this.treeTitle = '菜单权限'
      this.treeOpen = true
      this.keysId = row.id
      const keys = {
        "c": {
          menu_name: '新增权限',
          menu_id: 'c'
        },
        "r": {
          menu_name: '查询权限',
          menu_id: 'r'
        },
        "u": {
          menu_name: '修改权限',
          menu_id: 'u'
        },
        "d": {
          menu_name: '删除权限',
          menu_id: 'd'
        },
      }
      this.treeData = [];
      this.$http.get(roleApi.getRoleOne, { params: { permission_id: row.id } })
        .then(response => {
          let res = response.data.data
          let data = []
          res.forEach((item, index) => {
            if (item.children) {
              item.children.forEach(k => {
                let arr = k.permissions_list.slice(1, -1).split(',')
                k.children = []
                if (arr) {
                  arr.forEach(v => {
                    let msg = { ...keys[v] }
                    msg.menu_id = k.menu_id + msg.menu_id
                    data.push(msg)
                  })
                }
              })
            } else {
              let arr = item.permissions_list.slice(1, -1).split(',')
              if (arr) {
                item.children = []
                arr.forEach(v => {
                  let msg = { ...keys[v] }
                  msg.menu_id = item.menu_id + msg.menu_id
                  data.push(msg)
                })
              }
            }
          })
          this.$refs.tree.setCheckedNodes(data);
        })
    },
    // 菜单信息改装，加入curd
    transformMenuData(menuData) {
      return menuData.map((item, index) => {
        if (item.children) {
          this.transformMenuData(item.children)
        } else {
          item.children = [
            {
              menu_name: "新增权限",
              menu_id: item.menu_id + "c"
            },
            {
              menu_name: "查询权限",
              menu_id: item.menu_id + "r"
            },
            {
              menu_name: "修改权限",
              menu_id: item.menu_id + "u"
            },
            {
              menu_name: "删除权限",
              menu_id: item.menu_id + "d"
            }
          ]
        }
        return item
      })
    },
    // 确定修改当前角色的菜单权限信息
    handleSureKeys() {
      // let data = this.$refs.tree.getCheckedKeys()
      let data1 = this.$refs.tree.getCheckedKeys()
      let data2 = this.$refs.tree.getHalfCheckedKeys()
      let data = this.generateStrings([...data1, ...data2])
      let form1 = this.processArray(data)
      // 找到应该有的父元素，并进行赋值处理
      console.log(JSON.stringify(form1))
      let formData = {
        permission_id: this.keysId,
        permissions_list: JSON.stringify(form1)
      }
      let form = new FormData()
      // 遍历 msg 对象，并将键值对添加到 formData 中
      Object.keys(formData).forEach(key => {
        form.append(key, formData[key]);
      });
      let config = {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      };
      this.$http.post(roleApi.updataRoleMenu, form, config)
        .then(response => {
          if (response.data.code == 200) {
            this.$message({
              type: 'success',
              message: response.data.msg
            })
            this.treeOpen = false
          } else {
            this.$message({
              type: 'warning',
              message: response.data.msg
            })
          }
        })
        .catch(rek => {
          console.log(rek)
        })
    },
    // 处理菜单中选中的信息
    processArray(inputArray) {
      // 用一个对象来记录每个 menu_id 对应的权限集合
      let menuPermissions = {};

      // 遍历数组并处理每个元素
      inputArray.forEach(item => {
        if (typeof item === 'string') {
          // 如果是字符串，提取 menu_id 和权限
          let menuId = item.slice(0, -1); // 获取数字部分作为 menu_id
          let permission = item.slice(-1); // 获取最后一个字母作为权限

          // 如果 menu_id 不在 menuPermissions 中，初始化为空数组
          if (!menuPermissions[menuId]) {
            menuPermissions[menuId] = [];
          }

          // 如果权限不存在，添加到权限列表
          if (!menuPermissions[menuId].includes(permission)) {
            menuPermissions[menuId].push(permission);
          }
        }
      });

      // 将 menuPermissions 转换成指定的格式
      let result = [];
      for (let menuId in menuPermissions) {
        // 将权限数组转换为字符串并格式化为 '[c,r,u,d]'

        let permissionsStr = '[' + menuPermissions[menuId].join(',') + ']';

        result.push({
          menu_id: menuId,
          permissions_list: permissionsStr // 将权限列表设置为格式化的字符串
        });
      }

      return result;
    },
    // 数据同级化处理
    generateStrings(arr) {
      // 创建一个 Set 用于记录已经有后缀的数字（例如："1c", "1r" 等）
      let existingNumbers = new Set();

      // 遍历原始数组，收集已带后缀的数字部分
      arr.forEach(item => {
        if (typeof item === 'string' && /^\d+[crud]$/.test(item)) {
          // 提取数字部分
          let num = item.replace(/[crud]$/, '');
          existingNumbers.add(num);
        }
      });

      // 对所有数字进行排序（按升序）
      let result = [];
      let numbers = new Set();

      arr.forEach(item => {
        if (typeof item === 'number') {
          numbers.add(item.toString());
        }
      });

      let sortedNumbers = Array.from(numbers).sort((a, b) => a - b);

      // 先把已有后缀的数字加入结果
      arr.forEach(item => {
        if (typeof item === 'string' && /^\d+[crud]$/.test(item)) {
          result.push(item);
        }
      });

      // 生成每个数字的 "c", "r", "u", "d" 后缀形式，跳过已有后缀的数字
      sortedNumbers.forEach(num => {
        if (!existingNumbers.has(num)) {
          result.push(`${num}c`, `${num}r`, `${num}u`, `${num}d`);
        }
      });

      return result;
    }
  }
};
  </script>
  
  <style lang="scss" scoped>
.role-management {
  width: 100%;
  height: 100%;
  background-color: #ffffff;
  border-radius: 6px;
  .serch {
    height: 70px;
    // padding-top: 16px;
    // padding-bottom: 16px;
    padding: 16px 18px;
    box-sizing: border-box;
    position: relative;
    .demo-ruleForm {
      height: 100%;
      display: flex;
      justify-content: left;
      align-items: flex-start;
      flex-wrap: wrap;
    }
  }
  .table {
    height: 87%;
    position: relative;
    .jia_table {
      height: 100%;
      .el-table {
        height: 100%;
        background-image: url("../../img/home/placeholder_bottom.png");
        background-position: bottom;
        background-size: 100% 60%;
        background-repeat: no-repeat;
      }
      ::v-deep .el-table--border .el-table__cell,
      .el-table__body-wrapper .el-table--border.is-scrolling-left ~ .el-table__fixed {
        border-right: none;
      }
      ::v-deep .el-table__empty-block {
        // display: none !important;
        .el-table__empty-text {
          color: transparent;
        }
      }
      ::v-deep .el-empty {
        width: 307px;
        height: 353px;
        position: absolute;
        top: 50%;
        left: 50%;
        margin-left: -153px;
        margin-top: -176px;
        .el-empty__image img {
          vertical-align: top;
          height: 147%;
          width: 100%;
        }
        .el-empty__description {
          margin-top: 20px;
          margin-right: 70px;
        }
      }
    }
    .page {
      width: 100%;
      height: 33px;
      // background-color: pink;
      text-align: right;
      position: absolute;
      right: 0;
      bottom: -24px;
    }
  }
  ::v-deep .roleForm {
