      .el-input__inner {
        // width: 177px;
        // height: 33px;
        background: #f7f6fb;
        border-radius: 4px;
        border: 1px solid #dcdfe6;
        box-sizing: border-box;
      }
      .el-input__suffix-inner {
        border-left: 1px solid #dcdfe6;
      }
    }
  }
}
</style>